mapper.select:
select * from ( SELECT t.user_name as userName, t.avatar, t.sex, t.age, t.room_no as roomNo, t.room_id as roomId, t.is_room as isRoom, t.on_line as onLine, g.game_name as gameName, g.game_img as gameImg, o.*, (select ifnull(avg(score), 0) from taking_commnt where order_taking_id = o.id) as commentScore, (select count(*) from orders where order_taking_id = o.id and `state` = 2) as ordersCount, (st_distance (point (o.longitude, o.latitude),point(#{longitude},#{latitude}) ) *111195) as distance FROM order_taking o LEFT JOIN game g ON o.game_id = g.id LEFT JOIN tb_user t ON t.user_id = o.user_id WHERE t.user_id is not null
and g.banner_id = #{bannerid}
and g.id = #{id}
and o.is_recommend=#{isRecommend}
and t.sex=#{sex}
and o.city=#{city}
and (t.user_name like #{like} or g.game_name like #{like})
and o.classify=#{classify}
AND o.status =0 and o.isdelete=0 ) a order by onLine=1 desc,
money ${by},
`count` desc,
distance,
create_time desc

SELECT g.game_name as gameName, g.game_img as gameImg, t.avatar, t.room_no as roomNo, t.room_id as roomId, t.is_room as isRoom, t.on_line as onLine, t.user_name as userName, t.sex, t.age, (select ifnull(avg(score), 0) from taking_commnt where order_taking_id = o.id) as commentScore, o.count as ordersCount, o.* FROM order_taking o left join game g on o.game_id=g.id LEFT JOIN tb_user t ON t.user_id = o.user_id WHERE o.user_id = #{userId} and o.isdelete=0
and o.status =#{status}
order by o.update_time desc

SELECT t.user_name as userName, g.game_name as gameName, g.game_img as gameImg, t.room_no as roomNo, t.room_id as roomId, t.is_room as isRoom, t.avatar, t.on_line as onLine, t.age, t.sex, o.*, (select ifnull(avg(score), 0) from taking_commnt where order_taking_id = o.id) as commentScore, (select count(*) from orders where order_taking_id = o.id and `state` = 2) as ordersCount, (st_distance (point (o.longitude, o.latitude),point(#{longitude},#{latitude}) ) *111195) as distance FROM order_taking o left join game g on o.game_id=g.id left join tb_user t on o.user_id= t.user_id where t.user_id is not null
and o.game_id=#{gameId}
and o.status=#{status}
and t.user_name like #{userName}
and o.user_id=#{userId}
and o.classify=#{classify}
order by o.update_time desc

mapper.update:
update order_taking
set status=2
where user_id = #{userId}
